mapper.select:
select cr_team_room.resource_id, cr_team_room.team_template_id, cr_team_room.NAME, cr_team_room.description, cr_team_room.sub_type, cr_team_room.pre_skills, cr_team_room.train_skills, cr_team_room.start_time, cr_team_room.end_time, cr_team_room.difficulty, cr_team_room.time_line_config, cr_team_room.create_user_id, cr_team_room.modify_user_id, cr_team_room.local_scene_id, cr_team_room.copyed_topo_id, cr_team_template.duration_time, local_scene.start_time scene_start_time, local_scene.destory_time scene_end_time, local_scene.scene_status from cr_team_room left join cr_team_template on cr_team_room.team_template_id = cr_team_template.resource_id left join local_scene on cr_team_room.resource_id = local_scene.business_instance_id
cr_team_room.resource_id in
#{roomId}
('')
and cr_team_room.name like #{search}
and cr_team_room.difficulty = #{listReq.difficult}
and cr_team_room.name = #{listReq.name}
and cr_team_room.sub_type = #{listReq.category}
